 "content": "from collections import Counter, deque


def transform(grid):
    """Fix isolated single-cell anomalies using the surrounding shape."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    singletons = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            size = 0
            while q:
                rr, cc = q.popleft()
                size += 1
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            if size == 1:
                singletons.append((r, c))

    # A one-cell color intruding into a large solid color block is noise;
    # infer its intended color from the cardinal neighbors.
    for r, c in singletons:
        neighbors = [grid[nr][nc] for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                     if 0 <= nr < h and 0 <= nc < w]
        if not neighbors:
            continue
        counts = Counter(neighbors)
        best = max(counts.values())
        tied = [color for color, count in counts.items() if count == best]
        # tie-break toward the color most common in its cardinal neighborhood
        out[r][c] = tied[0]
    return out


